// Builds the embedded engine: one ES2020 script with no imports, no DOM and no Node APIs, that
// installs `globalThis.RingsideEngine` (see game/docs/engine-host.md). Every JSON file under the
// repo's content/ folder is inlined, so the default world needs no file access.
//
//   node packages/engine-host/scripts/build-bundle.mjs [--outfile <path>] [--minify]
//
// The default output is game/Assets/StreamingAssets/engine/engine.js (plus engine.js.map), which is
// generated and gitignored. `npm run build:engine-bundle` at the repo root runs this.

import { readdirSync, readFileSync, statSync } from 'node:fs';
import { dirname, join, relative, resolve, sep } from 'node:path';
import { fileURLToPath } from 'node:url';
import { build } from 'esbuild';

const packageRoot = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const repoRoot = resolve(packageRoot, '../..');
const contentRoot = join(repoRoot, 'content');
const DEFAULT_OUTFILE = join(repoRoot, 'game/Assets/StreamingAssets/engine/engine.js');
const CONTENT_MODULE = 'virtual:ringside-content';

function parseArgs(argv) {
  const options = { outfile: DEFAULT_OUTFILE, minify: false };
  for (let index = 0; index < argv.length; index += 1) {
    const arg = argv[index];
    if (arg === '--outfile') {
      options.outfile = resolve(argv[index + 1] ?? '');
      index += 1;
    } else if (arg === '--minify') {
      options.minify = true;
    } else {
      throw new Error(`Unknown argument: ${arg}`);
    }
  }
  return options;
}

/** Every .json file under `folder`, sorted, as paths relative to the content root with `/`. */
function listJsonFiles(folder) {
  const found = [];
  for (const name of readdirSync(folder).sort()) {
    const path = join(folder, name);
    if (statSync(path).isDirectory()) {
      found.push(...listJsonFiles(path));
    } else if (name.endsWith('.json')) {
      found.push(relative(contentRoot, path).split(sep).join('/'));
    }
  }
  return found;
}

/** `virtual:ringside-content`: every content JSON file, parsed, in one object. */
const contentPlugin = {
  name: 'ringside-content',
  setup(pluginBuild) {
    pluginBuild.onResolve({ filter: /^virtual:ringside-content$/ }, () => ({
      path: CONTENT_MODULE,
      namespace: 'ringside-content',
    }));
    pluginBuild.onLoad({ filter: /.*/, namespace: 'ringside-content' }, () => {
      const files = {};
      const watchFiles = [];
      for (const path of listJsonFiles(contentRoot)) {
        const absolute = join(contentRoot, path);
        files[path] = JSON.parse(readFileSync(absolute, 'utf8'));
        watchFiles.push(absolute);
      }
      return { contents: JSON.stringify(files), loader: 'json', watchFiles };
    });
  },
};

export async function buildEngineBundle({ outfile = DEFAULT_OUTFILE, minify = false } = {}) {
  const result = await build({
    entryPoints: [join(packageRoot, 'src/entry.ts')],
    outfile,
    bundle: true,
    format: 'iife',
    platform: 'neutral',
    // fflate and zod publish ES modules; `neutral` would otherwise look at `main` only.
    mainFields: ['module', 'main'],
    conditions: ['import', 'default'],
    target: 'es2020',
    sourcemap: 'external',
    minify,
    legalComments: 'none',
    charset: 'utf8',
    metafile: true,
    logLevel: 'warning',
    plugins: [contentPlugin],
    banner: {
      js: '// Ringside Booker engine bundle. Generated by packages/engine-host/scripts/build-bundle.mjs; do not edit.',
    },
  });
  // No Node built-in can sneak in: `neutral` refuses to resolve `node:` imports. Globals the code
  // reaches for at run time are checked by test/bundle.test.ts, which runs the bundle in a bare
  // context.
  const contentBytes = Object.entries(result.metafile.inputs)
    .filter(([path]) => path.startsWith('ringside-content:'))
    .reduce((sum, [, input]) => sum + input.bytes, 0);
  return { outfile, bytes: statSync(outfile).size, contentBytes };
}

if (process.argv[1] !== undefined && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const { outfile, bytes, contentBytes } = await buildEngineBundle(
    parseArgs(process.argv.slice(2)),
  );
  const megabytes = (count) => `${(count / (1024 * 1024)).toFixed(2)} MB`;
  console.log(
    `Engine bundle: ${relative(process.cwd(), outfile)} (${megabytes(bytes)}, of which content ${megabytes(contentBytes)})`,
  );
}
